function Profile() {
  const [likes, setLikes] = useState(0);
  function Bio() {
    const [draft, setDraft] = useState('');
    return <textarea value={draft} onChange={e => setDraft(e.target.value)} />;
  }
  return (
    <>
      <button onClick={() => setLikes(likes + 1)}>Like {likes}</button>
      <Bio />
    </>
  );
}
